288: impl<A, B> ZipImpl<A, B> for Zip<A, B>
289: where
290:     A: TrustedRandomAccess + Iterator,
291:     B: TrustedRandomAccess + Iterator,
292: {
293:     fn new(a: A, b: B) -> Self {
294:         let len = cmp::min(a.size(), b.size());
295:         Zip { a, b, index: 0, len }
296:     }
297: 
298:     #[inline]
299:     fn next(&mut self) -> Option<(A::Item, B::Item)> {
300:         if self.index < self.len {
301:             let i = self.index;
302:             // since get_unchecked executes code which can panic we increment the counters beforehand
303:             // so that the same index won't be accessed twice, as required by TrustedRandomAccess
304:             self.index += 1;
305:             // SAFETY: `i` is smaller than `self.len`, thus smaller than `self.a.len()` and `self.b.len()`
306:             unsafe {
307:                 Some((self.a.__iterator_get_unchecked(i), self.b.__iterator_get_unchecked(i)))
308:             }
309:         } else {
310:             None
311:         }
312:     }
